def bit_pack(*args):
    result = []
    current = 0
    bit = 7  # most significant bit position
    for b in args:
        if bit < 0:
            result.append(current)
            current = 0
            bit = 7
        if b:
            current |= (1 << bit)
        bit -= 1
    result.append(current)
    return bytes(result)

