    current = ""
    while i < n:
        if pointer[i] == "/":
            segments.append(current)
            current = ""
            i += 
        else:
            if pointer[i] == "~" and i + 1 < n:
                escape = pointer[i+1]
                if escape == "0":
                    current += "~"
                    i += 2
                elif escape == "1":
                    current += "/"
                    i += 2
                else:
                    current += pointer[i]
                    i += 1
            else:
                current += pointer[i]
                i += 1
    segments.append(current)
