                raise KeyError(f"List index {seg} is not an integer")
            if idx < 0 or idx >= len(current_doc):
                raise KeyError(f"List index {idx} out of range")
            current_doc = current_doc[idx]
        else:
            raise KeyError(f"Invalid type for segment {seg}")
    return current_doc"}

